def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = 0
    my_def = 0
    for me, op in history:
        if op == 'D':
            opp_def += 1
        if me == 'D':
            my_def += 1
    opp_coop_rate = (n - opp_def) / n

    remaining = 100 - n

    # Endgame: last round always defect (no future to lose)
    if remaining <= 1:
        return 'D'

    # Detect pure cooperator: exploit at endgame, otherwise mostly cooperate
    if opp_def == 0:
        if remaining <= 3:
            return 'D'
        # Occasional probe to grab 5 but keep partner cooperative
        if n >= 20 and n % 11 == 0:
            return 'D'
        return 'C'

    # Detect heavy defector: punish hard
    if opp_def * 4 >= n * 3 and n >= 6:
        # Rare olive branch to reset cooperation
        if n % 17 == 0:
            return 'C'
        return 'D'

    # Late-match defection push
    if remaining <= 2:
        return 'D'
    if remaining <= 5:
        # only defect if opponent rarely punishes (they've been cooperative recently)
        recent = history[-6:]
        rdef = sum(1 for _, o in recent if o == 'D')
        if rdef >= 2:
            return 'D'
        return 'C'

    last_me, last_opp = history[-1]

    # Recent rates
    look = 8 if n >= 8 else n
    recent = history[-look:]
    r_opp_def = sum(1 for _, o in recent if o == 'D')
    r_opp_coop = look - r_opp_def
    recent_coop_rate = r_opp_coop / look

    # Strong recent defection: retaliate
    if r_opp_def >= 3:
        # Try to break spiral occasionally
        if r_opp_def >= 5 or (n >= 10 and opp_def * 2 > n):
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Opponent just defected: retaliate most of the time
    if last_opp == 'D':
        # If long-run cooperative, forgive occasionally to restart
        if opp_coop_rate > 0.75 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent just cooperated
    if last_opp == 'C':
        # If we're in a good relationship and recently cooperative, stay C
        if recent_coop_rate >= 0.7:
            # Occasional probe only if long-run very cooperative and not too late
            if opp_coop_rate > 0.9 and remaining > 15 and rng.random() < 0.04:
                return 'D'
            return 'C'
        # Mixed relationship: cooperate but wary
        if recent_coop_rate >= 0.5:
            return 'C'
        # Recent mostly D but they just C: reward with C
        return 'C'

    return 'C'
